total_health = 999

def party_report(party):
    total_health = 0
    lowest_health = party[0]["health"]
    for member in party:
        total_health = total_health + member["health"]
        if member["health"] < lowest_health:
            lowest_health = member["health"]
    return {
        "member_count": len(party),
        "total_health": total_health,
        "lowest_health": lowest_health,
    }
